{"begin":"BEGIN_FSV-B19_autopac_generate_MAIN","stage":"autopac_generate","output":{"status":"READY","rego":"package external_pilot

import rego.v1

default allow := false

allow if {
    not blocked_from_purchase_order
}

blocked_from_purchase_order if {
    input.trusted.supplierOnHold == true
    input.trusted.holdType in {"Invoices", "All"}
}","reason":"Source VIS-FSV-B19-01 section 2.4 states that when a supplier is blocked with hold type 'Invoices', ERPNext will not allow Purchase Orders to be created for the supplier, and hold type 'All' applies both 'Invoices' and 'Payments' restrictions. Therefore, a Purchase Order creation request must be denied when trusted.supplierOnHold is true and trusted.holdType is 'Invoices' or 'All'. No other constraints are derivable from visible sources."},"end":"END_FSV-B19_autopac_generate_MAIN"}
